const listContextSteps = `-- name: ListContextSteps :many
SELECT step_seq, kind, status, request, response, error FROM execution_steps
WHERE org_id = $1 AND task_id = $2 AND step_seq < $3 AND created_at >= $4
ORDER BY step_seq, created_at, id LIMIT $5
`

type ListContextStepsParams struct {
	OrgID     uuid.UUID
	TaskID    uuid.UUID
	BeforeSeq int32
	Since     time.Time
	RowLimit  int32
}

type ListContextStepsRow struct {
	StepSeq  int32
	Kind     string
	Status   string
	Request  []byte
	Response []byte
	Error    []byte
}

// Các step trước một step, theo thứ tự, để dựng lại hội thoại.
func (q *Queries) ListContextSteps(ctx context.Context, arg ListContextStepsParams) ([]ListContextStepsRow, error) {
	rows, err := q.db.Query(ctx, listContextSteps,
		arg.OrgID,
		arg.TaskID,
		arg.BeforeSeq,
		arg.Since,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListContextStepsRow
	for rows.Next() {
		var i ListContextStepsRow
		if err := rows.Scan(
			&i.StepSeq,
			&i.Kind,
			&i.Status,
			&i.Request,
			&i.Response,
			&i.Error,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

