const taskRetrySafe = `-- name: TaskRetrySafe :one
SELECT agent_task_retry_safe($1)::boolean AS safe
`

// Lần thử trước của một bước có chắc chắn chưa gây tác động không (migration 00036):
// database quyết định, từ chỗ giữ của Gateway.
func (q *Queries) TaskRetrySafe(ctx context.Context, taskID uuid.UUID) (bool, error) {
	row := q.db.QueryRow(ctx, taskRetrySafe, taskID)
	var safe bool
	err := row.Scan(&safe)
	return safe, err
}
